package dashboard

import (
	"context"
	"encoding/xml"
	"io"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/statechart"
	"github.com/gitdek/invariant/internal/synth"
)

type reader665HTMLNode struct {
	name     string
	attrs    map[string]string
	text     string
	children []*reader665HTMLNode
}

func (n *reader665HTMLNode) all(name string) []*reader665HTMLNode {
	var out []*reader665HTMLNode
	if n.name == name {
		out = append(out, n)
	}
	for _, child := range n.children {
		out = append(out, child.all(name)...)
	}
	return out
}
func (n *reader665HTMLNode) hasClass(class string) bool {
	for _, word := range strings.Fields(n.attrs["class"]) {
		if word == class {
			return true
		}
	}
	return false
}
func (n *reader665HTMLNode) prose() string {
	if n.name == "style" || n.name == "script" {
		return ""
	}
	// A raw JSON record is still useful, but cannot satisfy the requirement
	// for a human-readable report beside the chart.
	if n.name == "pre" && (strings.HasPrefix(strings.TrimSpace(n.raw()), "{") || strings.HasPrefix(strings.TrimSpace(n.raw()), "[")) {
		return ""
	}
	out := n.text
	for _, c := range n.children {
		out += "\n" + c.prose()
	}
	return out
}
func (n *reader665HTMLNode) raw() string {
	out := n.text
	for _, child := range n.children {
		out += child.raw()
	}
	return out
}
func reader665HTML(t *testing.T, body string) *reader665HTMLNode {
	t.Helper()
	d := xml.NewDecoder(strings.NewReader(body))
	d.Strict = false
	d.AutoClose = xml.HTMLAutoClose
	d.Entity = xml.HTMLEntity
	root := &reader665HTMLNode{name: "document"}
	stack := []*reader665HTMLNode{root}
	for {
		tok, err := d.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
		switch v := tok.(type) {
		case xml.StartElement:
			n := &reader665HTMLNode{name: strings.ToLower(v.Name.Local), attrs: map[string]string{}}
			for _, a := range v.Attr {
				n.attrs[strings.ToLower(a.Name.Local)] = a.Value
			}
			parent := stack[len(stack)-1]
			parent.children = append(parent.children, n)
			stack = append(stack, n)
		case xml.EndElement:
			if len(stack) > 1 {
				stack = stack[:len(stack)-1]
			}
		case xml.CharData:
			parent := stack[len(stack)-1]
			parent.children = append(parent.children, &reader665HTMLNode{name: "#text", text: string(v)})
		}
	}
	return root
}
func reader665CSSRule(css, selector string) map[string]string {
	css = regexp.MustCompile(`(?s)/\*.*?\*/`).ReplaceAllString(css, "")
	out := map[string]string{}
	for _, m := range regexp.MustCompile(`(?s)([^{}]+)\{([^{}]*)\}`).FindAllStringSubmatch(css, -1) {
		for _, s := range strings.Split(m[1], ",") {
			if strings.TrimSpace(s) != selector {
				continue
			}
			for _, declaration := range strings.Split(m[2], ";") {
				k, v, ok := strings.Cut(declaration, ":")
				if ok {
					out[strings.TrimSpace(k)] = strings.TrimSpace(v)
				}
			}
		}
	}
	return out
}
func reader665Sizing(t *testing.T, css string) {
	t.Helper()
	frame := reader665CSSRule(css, ".reader-frame")
	if frame["overflow"] != "auto" && frame["overflow-x"] != "auto" && frame["overflow"] != "scroll" && frame["overflow-x"] != "scroll" {
		t.Error("reader frame does not scroll")
	}
	img := reader665CSSRule(css, ".reader-image")
	if img["width"] != "auto" || img["max-width"] != "none" || img["height"] != "auto" {
		t.Error("reader image must use its natural dimensions, including when wider than the card")
	}
}
func reader665Page(t *testing.T, body string, c *statechart.Result) {
	t.Helper()
	n := reader665HTML(t, body)
	if len(n.all("script")) != 0 || len(n.all("canvas")) != 0 {
		t.Fatal("evidence page requires script")
	}
	var css strings.Builder
	for _, style := range n.all("style") {
		css.WriteString(style.raw())
	}
	reader665Sizing(t, css.String())
	framed := false
	for _, div := range append(n.all("div"), n.all("figure")...) {
		if !div.hasClass("reader-frame") {
			continue
		}
		if div.attrs["tabindex"] != "0" || strings.TrimSpace(div.attrs["aria-label"]) == "" {
			t.Error("scrolling chart has no keyboard focus or accessible name")
		}
		for _, img := range div.all("img") {
			if img.hasClass("reader-image") && img.attrs["src"] != "" {
				framed = true
			}
		}
	}
	if !framed {
		t.Error("chart has no accessible natural-size scrolling frame")
	}
	text := strings.Join(strings.Fields(n.prose()), " ")
	for _, want := range []string{"Concrete members", "Initial members", "Unavailable", "occurrence", c.Report.Source.Tool.Image, c.Report.Source.Tool.JarSHA256} {
		if !strings.Contains(strings.ToLower(text), strings.ToLower(want)) {
			t.Errorf("HTML report omits %q outside raw JSON", want)
		}
	}
	for _, r := range c.Report.Rules {
		if !strings.Contains(text, strings.Join(strings.Fields(r.Says), " ")) {
			t.Error("HTML report lost exact rule wording")
		}
	}
	for _, meaning := range c.Report.CountMeanings {
		if !strings.Contains(text, strings.Join(strings.Fields(meaning), " ")) {
			t.Error("HTML report lost a count's meaning")
		}
	}
	for _, a := range c.Arrows {
		for _, step := range a.Members {
			if !strings.Contains(text, step.Action) {
				t.Errorf("visible occurrence action %q missing from HTML report", step.Action)
			}
		}
	}
	for _, a := range c.Report.Hidden {
		for _, rule := range a.HidingRules {
			if !strings.Contains(text, rule) {
				t.Errorf("hiding rule %q missing from HTML report", rule)
			}
		}
	}
	var memberDetails, occurrenceDetails bool
	for _, d := range n.all("details") {
		prose := strings.ToLower(d.prose())
		if strings.Contains(prose, "concrete members") {
			memberDetails = true
			if _, open := d.attrs["open"]; open {
				t.Error("member list starts expanded")
			}
		}
		if strings.Contains(prose, "occurrence") {
			occurrenceDetails = true
			if _, open := d.attrs["open"]; open {
				t.Error("occurrence list starts expanded")
			}
		}
	}
	if !memberDetails || !occurrenceDetails {
		t.Error("HTML report lacks complete collapsed member and occurrence sections")
	}
}

func TestReader665DashboardReportAndNaturalSize(t *testing.T) {
	f := reader631FixtureFor(t, 70, "Ready <script>literal</script> & exact words")
	r := reader631Repo(t, "owner/readable", strings.Repeat("6", 40), 665, []reader631Fixture{f}, reader631Archive(t, []reader631Fixture{f}, nil))
	s := &Server{Repos: []*Repo{r}, Cache: t.TempDir()}
	p := reader631Find(t, reader631Load(t, s, r), r.Name, f.Dir)
	if p.Status != "chart" {
		t.Fatalf("fixture did not reach presentation: %+v", p)
	}
	page := reader631GET(s, "GET", p.Page, "")
	if page.Code != 200 {
		t.Fatal("missing evidence page")
	}
	reader665Page(t, page.Body.String(), f.Report.Reader.Chart)
	if !strings.Contains(page.Header().Get("Content-Security-Policy"), "default-src 'none'") {
		t.Fatal("lost inert evidence-page policy")
	}
	cold := &Server{Repos: []*Repo{{Name: r.Name}}, Cache: s.Cache}
	cold.loadSnapshot()
	again := reader631GET(cold, "GET", p.Page, "")
	if again.Code != 200 || again.Body.String() != page.Body.String() || again.Header().Get("ETag") != page.Header().Get("ETag") {
		t.Fatal("restart lost complete report or immutable presentation")
	}
	if reader631GET(cold, "GET", p.Page, page.Header().Get("ETag")).Code != 304 {
		t.Fatal("report page lost conditional response")
	}
}

func TestReader665AllEvidencePagesUseTheSplit(t *testing.T) {
	// Use the existing executable TLC double and its strict command-line
	// checks to get valid proposal and option evidence through production APIs.
	tc, _ := reader603Tools(t)
	ws := t.TempDir()
	reader603Workspace(t, ws)
	old, _, err := formalize.Check(t.Context(), ws, tc)
	if err != nil {
		t.Fatal(err)
	}
	agent := comparison648Agent{run: func(_ context.Context, j synth.Job) (synth.Usage, error) {
		reader603Workspace(t, j.Workspace)
		reader603Write(t, filepath.Join(j.Workspace, "view.json"), strings.ReplaceAll(reader603View, "Working", "Revised working"))
		return synth.Usage{}, nil
	}}
	result, err := (formalize.Formalizer{Backend: agent, Toolchain: tc}).Formalize(t.Context(), formalize.Request{Repo: "owner/readable", Issue: 665, Previous: old}, t.TempDir())
	if err != nil || result == nil || result.Problem != "" {
		t.Fatalf("comparison fixture: %v %+v", err, result)
	}
	s := &Server{Repos: []*Repo{{Name: "owner/readable"}}, Cache: t.TempDir()}
	p := s.keepComparison(comparisonEvidence{Format: comparisonFormat, Repo: "owner/readable", Issue: 665, Proposal: result.Proposal})
	if p.Status != "chart" {
		t.Fatal("comparison fixture has no chart")
	}
	page := reader631GET(s, "GET", p.Page, "")
	c := result.Proposal.Reader.Comparison
	reader665Page(t, page.Body.String(), c.Candidate.Chart)
	reader665Page(t, page.Body.String(), c.Baseline.Chart)
	prose := reader665HTML(t, page.Body.String()).prose()
	for _, word := range []string{c.Baseline.Name, c.Candidate.Name, c.BaselineIdentity.ModelSHA256, c.CandidateIdentity.ViewSHA256, "equivalence"} {
		if !strings.Contains(prose, word) {
			t.Errorf("comparison report omits %q", word)
		}
	}
	previewWorkspace := t.TempDir()
	preview639Write(t, previewWorkspace, preview639Draft(t, 1, nil))
	preview := preview639Checked(t, previewWorkspace, tc)
	server := preview639Server(t, preview, "owner/readable", 666)
	options := preview639Choices(t, preview639Snapshot(t, server))
	for _, o := range options {
		page := reader631GET(server, "GET", o.Reader.Page, "")
		reader665Page(t, page.Body.String(), o.Preview.Model.Reader.Chart)
		prose := reader665HTML(t, page.Body.String()).prose()
		if !strings.Contains(strings.ToLower(prose), "unratified") || !strings.Contains(prose, o.Says) {
			t.Error("preview report lost its unratified option context")
		}
	}
}

func TestReader665CardsDoNotShrinkCharts(t *testing.T) {
	// The browser uses one image component for project, proposal, option and
	// table cards. Natural SVG pixels keep the renderer's >=10px labels legible.
	js := string(assets["/app.js"])
	start := strings.Index(js, "function readerEvidence(")
	if start < 0 {
		t.Fatal("missing shared reader card renderer")
	}
	end := strings.Index(js[start+1:], "\n  function ")
	if end < 0 {
		t.Fatal("cannot locate reader card renderer")
	}
	component := js[start : start+1+end]
	frame := regexp.MustCompile(`(?s)<(?:div|figure)\b[^>]*class="reader-frame"[^>]*>`).FindString(component)
	if !strings.Contains(frame, `tabindex="0"`) || !strings.Contains(frame, `aria-label="`) {
		t.Error("reader card needs a keyboard-accessible, named scroll frame")
	}
	for _, word := range []string{`class="reader-image"`, `src="${esc(r.svg)}"`, `href="${esc(r.page)}"`} {
		if !strings.Contains(component, word) {
			t.Errorf("card lost checked image or evidence link %s", word)
		}
	}
	reader665Sizing(t, string(assets["/style.css"]))
}

