package receipt_test

import (
	"encoding/json"
	"fmt"
	"html"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/tlc"
	"github.com/gitdek/invariant/internal/verify"
)

func TestReader665ReceiptReportIsCompleteAndCollapsed(t *testing.T) {
	c := receipt615Chart(t)
	for i := 0; i < 100; i++ {
		c.States[0].Members = append(c.States[0].Members, fmt.Sprintf("receipt-member-%03d", i))
	}
	c.Report.Counts["tlc_states"] += 100
	c.Report.Temporal = []tlc.TraceFile{{Module: "Temporal665", TLC: "TLC trace version", Check: "Eventually665", Violated: "Eventually665", Loop: 2, Stutters: true, States: []tlc.TraceState{
		{Index: 1, Action: "Initial trace action", TLA: map[string]string{"phase": "\"ready\""}, Vars: map[string]any{"phase": "ready"}},
		{Index: 2, Action: "Repeated trace action", Changed: []string{"phase"}, TLA: map[string]string{"phase": "\"waiting\""}, Vars: map[string]any{"phase": "waiting", "precise": json.Number("9007199254740993123456789")}},
	}}}
	r := receipt615Report(t, c, true)
	// The older fixture helper decodes through float64; retain the original
	// checked result so this test exercises lossless rendering, not that helper.
	r.Reader.Chart = c
	before := receipt615JSON(t, r)
	fingerprint, claim := verify.Fingerprint(*r), r.Claim()
	dir := t.TempDir()
	if err := receipt.Write(dir, r); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(dir, "receipt.md"))
	if err != nil {
		t.Fatal(err)
	}
	md := string(data)
	visible := html.UnescapeString(md)
	flat := strings.Join(strings.Fields(visible), " ")
	require := func(word string) {
		t.Helper()
		if word != "" && !strings.Contains(flat, strings.Join(strings.Fields(word), " ")) {
			t.Errorf("receipt report omits %q", word)
		}
	}
	for _, word := range []string{"Concrete members", "Initial members", "Temporal", "Eventually665", "Temporal665", "TLC trace version", "Repeated trace action", "9007199254740993123456789", "Loop", "Stutter"} {
		if !strings.Contains(strings.ToLower(flat), strings.ToLower(word)) {
			t.Errorf("receipt report omits %q", word)
		}
	}
	for _, s := range c.States {
		require(s.Label)
		for _, vs := range [][]string{s.Members, s.InitialMembers, s.ViolatedRules, s.UnavailableActions} {
			for _, v := range vs {
				require(v)
			}
		}
	}
	for _, rule := range c.Report.Rules {
		require(rule.Name)
		require(rule.Says)
		require(rule.SHA256)
	}
	for _, a := range c.Arrows {
		for _, step := range a.Members {
			require(step.From)
			require(step.Action)
			require(step.To)
		}
	}
	for _, a := range c.Report.Hidden {
		for _, id := range a.HidingRules {
			require(id)
		}
		for _, step := range a.Members {
			require(step.From)
			require(step.Action)
			require(step.To)
		}
	}
	for _, meaning := range c.Report.CountMeanings {
		require(meaning)
	}
	require(c.Report.Source.Tool.Image)
	require(c.Report.Source.Tool.JarSHA256)
	require(c.Report.Source.Config.Specification)
	if !strings.Contains(md, "```mermaid\n") || !strings.Contains(md, "adds no proof claim") {
		t.Fatal("receipt lost diagram or bounded-evidence qualification")
	}
	if strings.Contains(md, "<script") {
		t.Fatal("report interpreted literal evidence as HTML")
	}
	details := regexp.MustCompile(`(?s)<details\b([^>]*)>(.*?)</details>`).FindAllStringSubmatch(md, -1)
	members, occurrences := false, false
	for _, d := range details {
		body := html.UnescapeString(d[2])
		if strings.Contains(body, "receipt-member-099") {
			members = true
			if regexp.MustCompile(`\bopen\b`).MatchString(d[1]) {
				t.Error("long member list starts expanded")
			}
			for i := 0; i < 100; i++ {
				if !strings.Contains(body, fmt.Sprintf("receipt-member-%03d", i)) {
					t.Error("collapsed member list is truncated")
				}
			}
		}
		if strings.Count(body, "Poll") >= 2 {
			occurrences = true
			if regexp.MustCompile(`\bopen\b`).MatchString(d[1]) {
				t.Error("occurrence list starts expanded")
			}
		}
	}
	if !members || !occurrences {
		t.Error("receipt lacks closed, complete member and duplicate occurrence lists")
	}
	readerData, err := os.ReadFile(filepath.Join(dir, "reader.json"))
	if err != nil {
		t.Fatal(err)
	}
	// Compare JSON to retain exact large-number spelling through the writer.
	var original, actual any
	decode := func(b []byte, v *any) {
		d := json.NewDecoder(strings.NewReader(string(b)))
		d.UseNumber()
		if err := d.Decode(v); err != nil {
			t.Fatal(err)
		}
	}
	decode(receipt615JSON(t, r.Reader), &original)
	decode(readerData, &actual)
	if !reflect.DeepEqual(original, actual) {
		t.Fatal("reader.json changed or lost evidence")
	}
	if string(before) != string(receipt615JSON(t, r)) || verify.Fingerprint(*r) != fingerprint || r.Claim() != claim {
		t.Fatal("presentation changed receipt evidence or assurance")
	}
}

