package statechart_test

import (
	"encoding/json"
	"encoding/xml"
	"fmt"
	"reflect"
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/gitdek/invariant/internal/statechart"
)

// These are offline rendering workloads, not claims that a fixture ran TLC.
// The real examples remain covered by TestReader631ExampleViews's opt-in.
type reader665XML struct {
	XMLName  xml.Name
	Attrs    []xml.Attr     `xml:",any,attr"`
	Text     string         `xml:",chardata"`
	Children []reader665XML `xml:",any"`
}

func (n *reader665XML) attr(key string) string {
	for _, a := range n.Attrs {
		if a.Name.Local == key {
			return a.Value
		}
	}
	return ""
}
func (n *reader665XML) all(name string) []*reader665XML {
	var out []*reader665XML
	if n.XMLName.Local == name {
		out = append(out, n)
	}
	for i := range n.Children {
		out = append(out, n.Children[i].all(name)...)
	}
	return out
}
func (n *reader665XML) text() string {
	s := n.Text
	for i := range n.Children {
		s += n.Children[i].text()
	}
	return s
}
func (n *reader665XML) visible() string {
	var lines []string
	for _, x := range n.all("tspan") {
		lines = append(lines, x.text())
	}
	return strings.Join(lines, "\n")
}
func reader665Parse(t *testing.T, svg string) *reader665XML {
	t.Helper()
	var n reader665XML
	if err := xml.Unmarshal([]byte(svg), &n); err != nil {
		t.Fatal(err)
	}
	if n.XMLName.Local != "svg" {
		t.Fatal("not an SVG")
	}
	for _, name := range []string{"script", "foreignObject", "image", "style"} {
		if len(n.all(name)) != 0 {
			t.Fatalf("active or external SVG element %s", name)
		}
	}
	return &n
}
func reader665Render(t *testing.T, c *statechart.Result) *reader665XML {
	t.Helper()
	before := svg608JSON(t, c)
	svg, err := c.SVG()
	if err != nil {
		t.Fatal(err)
	}
	again, err := c.SVG()
	if err != nil || again != svg || string(svg608JSON(t, c)) != string(before) {
		t.Fatal("rendering is not deterministic and read-only")
	}
	n := reader665Parse(t, svg)
	metadata := n.all("metadata")
	if len(metadata) != 1 || metadata[0].attr("id") != "statechart-data" || metadata[0].text() != string(before) {
		t.Fatal("full exact result metadata was lost")
	}
	return n
}
func reader665Size(t *testing.T, n *reader665XML) (float64, float64) {
	t.Helper()
	var x, y, w, h float64
	if _, err := fmt.Sscanf(n.attr("viewBox"), "%f %f %f %f", &x, &y, &w, &h); err != nil || w <= 0 || h <= 0 {
		t.Fatal("invalid viewBox")
	}
	return w, h
}
func reader665Topology(t *testing.T, c *statechart.Result, n *reader665XML) {
	t.Helper()
	states, arrows, initials := map[string]int{}, map[string]int{}, map[string]int{}
	key := func(from, label, to string) string { return from + "\x00" + label + "\x00" + to }
	for _, g := range n.all("g") {
		if id := g.attr("data-state-id"); id != "" {
			states[id]++
		}
		if id := g.attr("data-initial"); id != "" {
			initials[id]++
		}
		if from := g.attr("data-from"); from != "" {
			arrows[key(from, g.attr("data-label"), g.attr("data-to"))]++
			titles := g.all("title")
			if len(titles) != 1 || titles[0].text() != g.attr("data-label") {
				t.Fatal("arrow lost exact label title")
			}
			if !strings.Contains(strings.Join(strings.Fields(g.visible()), " "), strings.Join(strings.Fields(g.attr("data-label")), " ")) {
				t.Fatal("arrow label missing from drawing")
			}
		}
	}
	if len(states) != len(c.States) || len(arrows) != len(c.Arrows) || len(initials) != len(c.Initial) {
		t.Fatal("drawing changed the chart topology")
	}
	for _, s := range c.States {
		if states[s.ID] != 1 {
			t.Fatal("state omitted or duplicated")
		}
	}
	for _, id := range c.Initial {
		if initials[id] != 1 {
			t.Fatal("initial omitted or duplicated")
		}
	}
	for _, a := range c.Arrows {
		if arrows[key(a.From, a.Label, a.To)] != 1 {
			t.Fatal("labeled arrow omitted or merged")
		}
	}
}

func TestReader665CompactExampleShapes(t *testing.T) {
	// Labels and endpoint shapes exercise the same four/three/two reader
	// states as the saved examples; membership pressure is deliberately large.
	cases := []struct {
		name   string
		labels []string
		edges  []svg613Edge
	}{
		{"two-phase commit", []string{"Preparing; coordinator has not decided", "Commit or abort decided", "Every resource manager committed", "Every resource manager aborted"}, []svg613Edge{
			{0, 1, "Commit after every resource manager prepares", false}, {0, 1, "Coordinator aborts", false},
			{0, 3, "Resource manager chooses to abort", false}, {1, 2, "Resource manager receives commit", false},
			{1, 3, "Resource manager receives abort", false}, {1, 3, "Resource manager chooses to abort", false},
			{0, 0, "Resource manager prepares", false}, {0, 0, "Resource manager chooses to abort", false},
			{0, 0, "Coordinator receives prepared message", false}, {1, 1, "Resource manager prepares", false},
			{1, 1, "Resource manager chooses to abort", false}, {1, 1, "Resource manager receives commit", false},
			{1, 1, "Resource manager receives abort", false}, {1, 1, "Coordinator receives prepared message", false},
			{2, 2, "Resource manager receives commit", false}, {3, 3, "Resource manager receives abort", false},
		}},
		{"log buffer", []string{"Buffer empty", "Lines buffered for shipping", "Oldest buffered line awaits retry"}, []svg613Edge{
			{0, 1, "Producer writes a line into the buffer", false}, {1, 0, "Ship the oldest line", false},
