	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c := svg613Chart(t, tc.labels, []int{0}, tc.edges)
			// Renderer input is explanatory data. These extra concrete identities
			// stress report size without pretending to be an exploration result.
			for i := 0; i < 210; i++ {
				c.States[0].Members = append(c.States[0].Members, fmt.Sprintf("member-%019d", i))
