			for _, s := range n.all("svg") {
				if size := s.attr("font-size"); size != "" && svg608Number(t, size) < 10 {
					t.Fatal("chart made compact by shrinking its font")
				}
			}
			if strings.Contains(n.visible(), "Concrete members:") {
