func TestReader665WrapsLabelsAndCompactsLoops(t *testing.T) {
	label := strings.TrimSpace(strings.Repeat("Read every exact <&> word ", 12))
	arrow := strings.TrimSpace(strings.Repeat("Continue with exact words ", 10))
	c := svg613Chart(t, []string{label, "Done"}, []int{0}, []svg613Edge{{0, 1, arrow, false}})
	n := reader665Render(t, c)
	for _, g := range n.all("g") {
		if g.attr("data-state-id") == "" && g.attr("data-from") == "" {
			continue
		}
		for _, title := range g.all("title") {
			if title.text() != label && title.text() != arrow {
				continue
			}
			if g.attr("data-label") != title.text() {
				t.Error("state or arrow lacks exact data-label")
			}
			if len(g.all("tspan")) < 3 {
				t.Error("long space-separated label was not wrapped")
			}
			for _, line := range g.all("tspan") {
				if utf8.RuneCountInString(line.text()) > 100 {
					t.Error("label still has an excessively long visible line")
				}
			}
		}
	}
	reader665Topology(t, c, n)
	base := svg613Chart(t, []string{"Ready", "Done"}, []int{0}, []svg613Edge{{0, 1, "Go", false}})
	edges := []svg613Edge{{0, 1, "Go", false}}
	for i := 0; i < 24; i++ {
		edges = append(edges, svg613Edge{0, 0, fmt.Sprintf("Wait %02d", i), false})
	}
	dense := svg613Chart(t, []string{"Ready", "Done"}, []int{0}, edges)
	a, b := reader665Render(t, base), reader665Render(t, dense)
	wa, _ := reader665Size(t, a)
	wb, _ := reader665Size(t, b)
	if wb > wa+100 {
		t.Errorf("self-loops spread the drawing horizontally: %g -> %g", wa, wb)
	}
	reader665Topology(t, dense, b)
	// Lists remain visible under their owner, not silently dropped as stutter.
	var owner *reader665XML
	for _, g := range b.all("g") {
		if g.attr("data-state-id") == dense.Initial[0] {
			owner = g
		}
	}
	if owner == nil {
		t.Fatal("missing loop owner")
	}
	stateRect := owner.all("rect")[0]
	bottom := svg608Number(t, stateRect.attr("y")) + svg608Number(t, stateRect.attr("height"))
	for _, g := range b.all("g") {
		if g.attr("data-from") == dense.Initial[0] && g.attr("data-to") == dense.Initial[0] {
			for _, span := range g.all("tspan") {
				if svg608Number(t, span.attr("y")) < bottom {
					t.Error("self-loop label is not listed below its state")
				}
			}
		}
	}
}

func TestReader665ComparisonSplit(t *testing.T) {
	a := comparison648Snapshot(t, 1, "Poll", comparison648View)
	b := comparison648Snapshot(t, 2, "Poll", strings.ReplaceAll(comparison648View, "Done", "Done <&> safely"))
	b.Lock.Bounds = map[string]string{"Limit": "3"}
	b.Chart.Report.Source.Config.Constants = b.Lock.Bounds
	c, err := statechart.Compare(a, b)
	if err != nil {
		t.Fatal(err)
	}
	before := comparison648JSON(t, c)
	svg, err := c.SVG()
	if err != nil {
		t.Fatal(err)
	}
	n := reader665Parse(t, svg)
	var retained bool
	for _, m := range n.all("metadata") {
		var saved statechart.Comparison
		if json.Unmarshal([]byte(m.text()), &saved) == nil && reflect.DeepEqual(&saved, c) {
			retained = true
		}
	}
	if !retained {
		t.Error("comparison lacks complete inert comparison metadata")
	}
	for _, bad := range []string{"Concrete members:", "SHA-256:", c.BaselineIdentity.ModelSHA256, c.CandidateIdentity.ViewSHA256} {
		if strings.Contains(n.visible(), bad) {
			t.Errorf("comparison still draws detailed report %q", bad)
		}
	}
	for _, word := range []string{"added", "removed", "scope", "proof", a.Name, b.Name} {
		if !strings.Contains(strings.ToLower(n.visible()), strings.ToLower(word)) {
			t.Errorf("comparison caption/legend omits %q", word)
		}
	}
	counts := map[string]int{}
	for _, g := range n.all("g") {
		if g.attr("data-state-id") != "" {
			counts[g.attr("data-comparison-side")]++
		}
	}
	if counts["baseline"] != len(a.Chart.States) || counts["candidate"] != len(b.Chart.States) {
		t.Fatal("comparison dropped a chart")
	}
	if string(comparison648JSON(t, c)) != string(before) {
		t.Fatal("comparison rendering changed evidence")
	}
}
